"""URL slugs for titles."""
import re
import unicodedata


def _normalize(title):
    """Lower-case ASCII text, runs of non-alphanumerics become single hyphens."""
    text = unicodedata.normalize("NFKD", title)
    text = "".join(ch for ch in text if not unicodedata.combining(ch)).lower()
    slug = re.sub(r"[^a-z0-9]+", "-", text).strip("-")
    return slug or "untitled"


def _truncate_words(slug, max_length):
    """Shorten slug to the longest run of whole leading words that fits.

    If the first word alone is longer than max_length, cut it to max_length.
    The result never starts or ends with a hyphen and is never longer than
    max_length.
    """
    if len(slug) <= max_length:
        return slug
    # Build up whole words separated by hyphens until adding the next word
    # would exceed max_length.
    words = slug.split("-")
    result = ""
    for word in words:
        if not result:
            candidate = word
        else:
            candidate = result + "-" + word
        if len(candidate) <= max_length:
            result = candidate
        else:
            break
    if not result:
        # First word alone is longer than max_length: cut it.
        result = words[0][:max_length]
    # Defensive: strip any leading/trailing hyphen (shouldn't happen here).
    return result.strip("-")


def slugify(title, max_length=None):
    """Lower-case ASCII words joined by hyphens, optionally length-limited."""
    slug = _normalize(title)
    if max_length is None:
        return slug
    if max_length < 1:
        raise ValueError("max_length must be at least 1")
    return _truncate_words(slug, max_length)


def unique_slug(title, taken, max_length=None):
    """Return a slug for title not present in taken, adding numeric suffixes."""
    if max_length is None:
        base = slugify(title)
        if base not in taken:
            return base
        n = 2
        while True:
            candidate = f"{base}-{n}"
            if candidate not in taken:
                return candidate
            n += 1

    if max_length < 1:
        raise ValueError("max_length must be at least 1")

    n = 2
    while True:
        suffix = f"-{n}"
        room = max_length - len(suffix)
        if room < 1:
            raise ValueError("max_length leaves no room for the base slug")
        base = slugify(title, room)
        candidate = base + suffix
        if candidate not in taken:
            return candidate
        n += 1
